class TFMLogicStepOperatorThrowError extends TFMLogicBlock implements TFMLogicStepOperatorInterface
{
    LabelString textToThrow;

}

Method.Source:
[TFMParameter('')]
public LabelString parmErrorText(LabelString _textToThrow = textToThrow)
{
    textToThrow = _textToThrow;
    if (!textToThrow)
    {
        textToThrow = "@TFM:Anerrorhasoccured";
    }
    return textToThrow;
}

public str runLogic ( TFMRequestElement _request )
{
    throw Error ( textToThrow);
    return '';
}
